  elif actions!=["no-op"]:raise ValueError("unrelated mutation or destruction")
 if not forgotten or forgotten!=request["ids"]:raise ValueError("handoff inventory mismatch")
 prior={r["address"]:r["values"]["id"] for r in plan["prior_state"]["values"]["root_module"]["resources"]}
