  if resource.get("mode","managed")!="managed":continue
  base=(resource.get("module","")+".").lstrip(".")+resource["type"]+"."+resource["name"]
  for instance in resource["instances"]:
   suffix="["+json.dumps(instance["index_key"],ensure_ascii=False)+"]" if "index_key" in instance else ""
   result[base+suffix]=instance["attributes"]["id"]
 return result
try:
