 if request["approved"] is not True:raise ValueError("approval required")
 if hashlib.sha256(raw).hexdigest()!=request["sha256"]:raise ValueError("backup hash mismatch")
 if state["lineage"]!=request["lineage"] or state["serial"]!=request["serial"]:raise ValueError("backup identity mismatch")
 inventory=ids(state)
 if not inventory or inventory!=request["ids"]:raise ValueError("object inventory mismatch")
 if pathlib.Path("terraform.tfstate").exists():
  print("existing state must be reviewed separately",file=sys.stderr)
  raise SystemExit(3)
 tf=os.environ.get("OPSFORGE_TERRAFORM","terraform")
 p=subprocess.run([tf,"state","push",str(backup)],capture_output=True,text=True,encoding="utf8")
 if p.returncode!=0:raise ValueError("native state push rejected")
 restored=json.loads(pathlib.Path("terraform.tfstate").read_text(encoding="utf8"))
 if restored["lineage"]!=request["lineage"] or ids(restored)!=inventory:raise ValueError("post-restore identity mismatch")
 print(json.dumps({"restored":True,"ids":inventory,"external_resources_verified":False},sort_keys=True))
