import json,os,pathlib,subprocess,sys
tf=os.environ.get("OPSFORGE_TERRAFORM","terraform")
def invoke(args):
 p=subprocess.run([tf,*args],capture_output=True,text=True,encoding="utf8")
 if p.returncode:raise ValueError("Terraform rejected operation")
 return p.stdout
def inventory(state):
 result={}
 for r in state.get("resources",[]):
  if r.get("mode","managed")!="managed":continue
  base=(r.get("module","")+".").lstrip(".")+r["type"]+"."+r["name"]
  for i in r.get("instances",[]):
   key="["+json.dumps(i["index_key"],ensure_ascii=False)+"]" if "index_key" in i else ""
   result[base+key]=i["attributes"]["id"]
 return result
try:
 request=json.loads(pathlib.Path(sys.argv[1]).read_text(encoding="utf8"))
 approved=json.loads(pathlib.Path("fixtures/approved-backend.json").read_text(encoding="utf8"))
 if request["environment"]!=approved["environment"] or request["path"]!=approved["path"]:raise ValueError("backend selection not approved")
 dest=pathlib.Path(request["path"])
 if dest.is_absolute() or ".." in dest.parts or not dest.is_file():raise ValueError("missing or unsafe approved state")
 state=json.loads(dest.read_text(encoding="utf8"))
 if state["lineage"]!=approved["lineage"] or state["serial"]!=approved["serial"] or inventory(state)!=approved["ids"]:raise ValueError("state identity mismatch")
 # No migration, import, push or apply. Reconfigure only after all identity checks.
 invoke(["init","-input=false","-no-color","-reconfigure","-backend-config=path="+request["path"]])
 invoke(["plan","-input=false","-no-color","-out=review.plan"])
 plan=json.loads(invoke(["show","-json","review.plan"]))
 if any(r["change"]["actions"]!=["no-op"] for r in plan.get("resource_changes",[])):raise ValueError("reconfigured plan is not no-op; stop")
 if len(plan.get("resource_changes",[]))!=len(approved["ids"]):raise ValueError("incomplete plan inventory")
 print(json.dumps({"reconfigured":True,"lineage":state["lineage"],"ids":approved["ids"],"plan_noop":True,"cloud_verified":False},sort_keys=True))
except (ValueError,KeyError,TypeError,OSError):
 print("backend recovery refused",file=sys.stderr)
 raise SystemExit(2)

```

实现 recover-backend.py：读取请求环境/后端 path，先对照只读批准记录，再只读核对该状态的 lineage、serial 与完整资源地址→ID。身份不符、未批准路径或环境必须退出 2，且不能改变当前后端元数据或任一状态。全部一致后只允许 init -reconfigure 到批准 local 后端并保存计划，计划必须覆盖全部原对象且全部 no-op；输出 reconfigured/lineage/ids/plan_noop/cloud_verified:false。不要 migrate、import、push、apply 或重建对象。可信验收先真实创建临时批准状态，再把后端错误配置到拼错路径，原生 plan 显示两个 create；修复必须重新找回同一 lineage 和 ID，原状态字节不变。批准记录由验收产生，示例不是真实状态。此本地模型训练后端 key 故障恢复，云对象存在性和业务健康没有验证。

