locals {
 normalized = [for s in var.services : { name = lower(trimspace(s.name)), description = s.description, replicas = s.replicas }]
 grouped = { for s in local.normalized : s.name => s... }
 unique = { for k, entries in local.grouped : k => entries[0] }
 unambiguous = alltrue([for entries in values(local.grouped) : length(distinct([for s in entries : jsonencode(s)])) == 1])
}
resource "terraform_data" "service" {
 for_each = local.unique
 input = each.value
